    71→// Core import logic - testable with injected dependencies
    72→export async function importBackupCore(
    73→  formData: FormData,
    74→  strategy: ConflictResolutionStrategy,
    75→  options: {
    76→    createBackupBeforeImport: boolean;
    77→    importPhotos: boolean;
    78→    importAuditLogs: boolean;
    79→  },
    80→  deps: RestoreDependencies
    81→): Promise<ImportResult> {
    82→  const session = await deps.requireAdmin();
    83→
    84→  try {
    85→    const file = formData.get("file") as File;
    86→    if (!file) {
    87→      throw new Error("No file provided");
    88→    }
    89→
    90→    // Convert file to buffer
    91→    const arrayBuffer = await file.arrayBuffer();
    92→    const buffer = Buffer.from(arrayBuffer);
    93→
    94→    // Validate backup first
    95→    const validator = deps.createValidator(buffer);
    96→    const validationResult = await validator.validate();
    97→
    98→    if (!validationResult.isValid) {
    99→      throw new Error(`Invalid backup: ${validationResult.errors.join(", ")}`);
   100→    }
   101→
   102→    let backupCreated: string | undefined;
   103→
   104→    // Create backup before import if requested
   105→    if (options.createBackupBeforeImport && deps.gatherBackupData) {
   106→      backupCreated = await createPreImportBackup(deps);
   107→    }
   108→
   109→    // Start database transaction for atomic import
   110→    const importResult = await deps.db.$transaction(async (tx: any) => {
   111→      // Create conflict resolver
   112→      const resolver = deps.createConflictResolver(strategy, {
   113→        id: session.id,
   114→        email: session.email,
   115→        name: session.name || null,
   116→      });
   117→
   118→      // Import data
   119→      const { statistics, errors, warnings } = await resolver.importData(
   120→        validator.getExtractedFiles(),
   121→        validationResult.conflicts
   122→      );
   123→
   124→      // Import photos if requested
   125→      if (options.importPhotos) {
   126→        const photosImported = await importPhotosCore(
   127→          validator.getExtractedFiles(),
   128→          deps
   129→        );
   130→        statistics.photosImported = photosImported;
   131→      }
   132→
   133→      // Log the import action
   134→      await tx.auditLog.create({
   135→        data: {
   136→          userId: session.id,
   137→          action: "CREATE",
   138→          entityType: "BACKUP_IMPORT",
   139→          entityId: null,
   140→          newData: {
   141→            timestamp: new Date().toISOString(),
   142→            strategy,
   143→            statistics: statistics as any,
   144→            backupCreated,
   145→          },
   146→        },
   147→      });
   148→
   149→      return {
   150→        success: errors.length === 0,
   151→        importedAt: new Date().toISOString(),
   152→        importedBy: {
   153→          id: session.id,
   154→          email: session.email,
   155→          name: session.name || null,
   156→        },
   157→        strategy,
   158→        statistics,
   159→        backupCreated,
   160→        errors,
   161→        warnings,
   162→      };
   163→    });
   164→
   165→    return importResult;
   166→  } catch (error) {
   167→    console.error("Backup import error:", error);
   168→
   169→    // Log failed import attempt
   170→    try {
   171→      await deps.db.auditLog.create({
   172→        data: {
   173→          userId: session.id,
   174→          action: "CREATE",
   175→          entityType: "BACKUP_IMPORT_FAILED",
   176→          entityId: null,
   177→          newData: {
   178→            timestamp: new Date().toISOString(),
   179→            error: error instanceof Error ? error.message : "Unknown error",
   180→          },
   181→        },
   182→      });
   183→    } catch (logError) {
   184→      console.error("Failed to log import error:", logError);
   185→    }
