   193→// Core import history logic - testable with injected dependencies
   194→interface ImportHistoryEntry {
   195→  id: string;
   196→  importedAt: string;
   197→  importedBy: string;
   198→  strategy: string;
   199→  statistics: Record<string, unknown>;
   200→  success: boolean;
   201→}
   202→
   203→interface AuditLogWithUser {
   204→  id: string;
   205→  createdAt: Date;
   206→  entityType: string;
   207→  newData: Record<string, unknown>;
   208→  user: {
   209→    email: string;
   210→    name: string | null;
   211→  };
   212→}
   213→
   214→export async function getImportHistoryCore(
   215→  deps: RestoreDependencies
   216→): Promise<ImportHistoryEntry[]> {
   217→  await deps.requireAdmin();
   218→
   219→  const auditLogs = await deps.db.auditLog.findMany({
   220→    where: {
   221→      entityType: {
   222→        in: ["BACKUP_IMPORT", "BACKUP_IMPORT_FAILED"],
   223→      },
   224→    },
   225→    include: {
   226→      user: {
   227→        select: {
   228→          email: true,
   229→          name: true,
   230→        },
   231→      },
   232→    },
   233→    orderBy: {
   234→      createdAt: "desc",
   235→    },
   236→    take: 50,
   237→  });
   238→
   239→  return auditLogs.map((log: unknown) => {
   240→    const typedLog = log as AuditLogWithUser;
   241→    const strategy = String(typedLog.newData.strategy || "unknown");
   242→    const statistics = typeof typedLog.newData.statistics === 'object' && typedLog.newData.statistics !== null
   243→      ? (typedLog.newData.statistics as Record<string, unknown>)
   244→      : {};
   245→
   246→    return {
   247→      id: typedLog.id,
   248→      importedAt: typedLog.createdAt.toISOString(),
   249→      importedBy: typedLog.user.name || typedLog.user.email,
   250→      strategy,
   251→      statistics,
   252→      success: typedLog.entityType === "BACKUP_IMPORT",
   253→    };
   254→  });
   255→}
   256→
   257→async function createPreImportBackup(deps: RestoreDependencies): Promise<string> {
   258→  if (!deps.gatherBackupData) {
   259→    throw new Error("gatherBackupData not available");
   260→  }
   261→
   262→  try {
   263→    // Gather current data for backup
   264→    const { metadata, data, photos } = await deps.gatherBackupData({
   265→      includePhotos: true,
   266→      includeAuditLogs: true,
   267→      auditLogDays: 90,
   268→    });
   269→
   270→    // Create backup filename with timestamp
   271→    const timestamp = new Date().toISOString().replace(/[:.]/g, "-");
   272→    const filename = `pre-import-backup-${timestamp}.zip`;
   273→    const backupPath = join(
   274→      process.env.STORAGE_LOCAL_PATH || "./data/uploads",
   275→      "backups"
   276→    );
   277→
   278→    // Ensure backup directory exists
   279→    await mkdir(backupPath, { recursive: true });
   280→
   281→    const fullPath = join(backupPath, filename);
   282→
   283→    // Create ZIP archive
   284→    return new Promise((resolve, reject) => {
   285→      const archive = archiver("zip", { zlib: { level: 9 } });
   286→      const output = require("fs").createWriteStream(fullPath);
   287→
   288→      output.on("close", () => {
   289→        resolve(filename);
   290→      });
   291→
   292→      archive.on("error", (err: Error) => {
   293→        reject(err);
   294→      });
   295→
   296→      archive.pipe(output);
   297→
   298→      // Add metadata and data files
   299→      archive.append(JSON.stringify(metadata, null, 2), {
   300→        name: "metadata.json",
   301→      });
   302→      archive.append(JSON.stringify(data.people, null, 2), {
   303→        name: "data/people.json",
   304→      });
   305→      archive.append(JSON.stringify(data.relationships, null, 2), {
   306→        name: "data/relationships.json",
   307→      });
   308→      archive.append(JSON.stringify(data.users, null, 2), {
   309→        name: "data/users.json",
   310→      });
   311→      archive.append(JSON.stringify(data.suggestions, null, 2), {
   312→        name: "data/suggestions.json",
   313→      });
   314→      archive.append(JSON.stringify(data.settings, null, 2), {
   315→        name: "data/settings.json",
   316→      });
   317→
   318→      if (data.auditLogs) {
   319→        archive.append(JSON.stringify(data.auditLogs, null, 2), {
   320→          name: "data/audit-logs.json",
   321→        });
   322→      }
   323→
   324→      // Add photos
   325→      if (photos.length > 0) {
   326→        addPhotosToBackupArchive(archive, photos);
   327→      } else {
   328→        archive.finalize();
   329→      }
   330→    });
   331→  } catch (error) {
   332→    console.error("Failed to create pre-import backup:", error);
   333→    throw new Error("Failed to create backup before import");
   334→  }
   335→}
   336→
   337→async function addPhotosToBackupArchive(
   338→  archive: archiver.Archiver,
   339→  photos: Array<{ id: string; photoUrl: string | null }>
   340→): Promise<void> {
   341→  for (const person of photos) {
   342→    if (!person.photoUrl) continue;
   343→
   344→    try {
   345→      // Extract the file path from the URL
   346→      const urlParts = person.photoUrl.split("/api/uploads/");
   347→      if (urlParts.length !== 2) continue;
   348→
   349→      const filePath = urlParts[1];
   350→      const storagePath = process.env.STORAGE_LOCAL_PATH || "./data/uploads";
   351→      const fullPath = join(storagePath, filePath);
   352→
   353→      // Read the file
   354→      const fileBuffer = await require("fs/promises").readFile(fullPath);
   355→
   356→      // Extract original filename
   357→      const originalName = filePath.split("-").slice(1).join("-");
   358→
   359→      // Add to archive
   360→      archive.append(fileBuffer, {
   361→        name: `photos/${person.id}/${originalName}`,
   362→      });
   363→    } catch (error) {
   364→      console.warn(`Failed to add photo for person ${person.id}:`, error);
   365→    }
   366→  }
   367→
   368→  archive.finalize();
   369→}
   370→
   371→async function importPhotosCore(
   372→  extractedFiles: Map<string, any>,
   373→  deps: RestoreDependencies
   374→): Promise<number> {
   375→  const storage = deps.getStorageAdapter();
   376→  let importedCount = 0;
   377→
   378→  for (const [filePath, fileBuffer] of extractedFiles.entries()) {
   379→    if (!filePath.startsWith("photos/") || filePath.endsWith("/")) {
   380→      continue;
   381→    }
   382→
   383→    try {
   384→      // Extract person ID and filename from path: photos/{personId}/{filename}
   385→      const pathParts = filePath.split("/");
   386→      if (pathParts.length !== 3) continue;
   387→
   388→      const personId = pathParts[1];
   389→      const filename = pathParts[2];
   390→
   391→      // Check if person exists
   392→      const person = await deps.db.person.findUnique({
   393→        where: { id: personId },
   394→      });
   395→      if (!person) {
   396→        console.warn(`Skipping photo for non-existent person: ${personId}`);
   397→        continue;
   398→      }
   399→
   400→      // Upload photo to storage
   401→      const storedPath = await storage.upload(fileBuffer, filename, "image/jpeg");
   402→      const photoUrl = storage.getUrl(storedPath);
   403→
   404→      // Update person with photo URL
   405→      await deps.db.person.update({
   406→        where: { id: personId },
   407→        data: { photoUrl },
   408→      });
   409→
   410→      importedCount++;
   411→    } catch (error) {
   412→      console.warn(`Failed to import photo ${filePath}:`, error);
   413→    }
   414→  }
   415→
   416→  return importedCount;
   417→}
   418→
   419→// Public API - uses default dependencies (for production use)
   420→export async function validateBackup(
   421→  formData: FormData
   422→): Promise<ValidationResult> {
   423→  return validateBackupCore(formData, defaultDependencies);
   424→}
   425→
   426→export async function importBackup(
   427→  formData: FormData,
   428→  strategy: ConflictResolutionStrategy,
   429→  options: {
   430→    createBackupBeforeImport: boolean;
   431→    importPhotos: boolean;
   432→    importAuditLogs: boolean;
   433→  }
   434→): Promise<ImportResult> {
   435→  return importBackupCore(formData, strategy, options, defaultDependencies);
   436→}
   437→
   438→export async function getImportHistory(): Promise<
   439→  Array<{
   440→    id: string;
   441→    importedAt: string;
   442→    importedBy: string;
   443→    strategy: string;
   444→    statistics: any;
   445→    success: boolean;
   446→  }>
   447→> {
   448→  return getImportHistoryCore(defaultDependencies);
   449→}
